"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3527],{5474(e){e.exports=JSON.parse('{"title":"\uc5b4\ub5a4 \uacbd\uc6b0\uc5d0 devDependencies\ub97c \uc0ac\uc6a9\ud574\uc57c \ud560\uae4c","date":"2024-11-30","coverUrl":null,"html":"<h2 data-notion-block-id=\\"150e548d-8a8e-807a-9538-f2883fc9c306\\" id=\\"150e548d-8a8e-807a-9538-f2883fc9c306\\">\uc5b4\ub5a4 \uacbd\uc6b0\uc5d0 <code>devDependencies</code>\ub97c \uc0ac\uc6a9\ud574\uc57c \ud560\uae4c</h2><a href=\\"https://angelika.me/2024/11/11/dependencies-vs-dev-dependencies-javascript-apps/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://angelika.me/2024/11/11/dependencies-vs-dev-dependencies-javascript-apps/</a><p data-notion-block-id=\\"150e548d-8a8e-804e-8289-f85af2d94a1d\\"><b>\uc2ec\uc724\uc12d</b>: package.json\uc758 <code>dependencies</code>\uc640 <code>devDependencies</code>\uac00 \ub2e4\ub978 \uc810\uacfc <code>devDependencies</code>\uc5d0 \ud3ec\ud568\ud560 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 \uc5b4\ub5bb\uac8c \uacb0\uc815\ud574\uc57c \ud560\uc9c0\uc640 <code>devDependencies</code>\ub85c \uad6c\ubd84\ud558\ub294 \uac83\uc774 \uc911\uc694\ud55c \uc774\uc720\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc815\ub2f5\uc740 \uc5c6\uc9c0\ub9cc, \uc811\uadfc\ubc29\uc2dd\uc744 \uc5b4\ub5bb\uac8c \uc124\uc815\ud558\ub294 \uc9c0\uc5d0 \ub530\ub77c CI \uc124\uc815 \ubc29\uc2dd\uc774 \ubaa8\ub450 \ub2ec\ub77c\uc9c8 \uac83 \uac19\uc544 \uc7a5\ub2e8\uc810\uc744 \ucda9\ubd84\ud788 \uace0\ub824\ud574\uc57c \ud560 \uac83 \uac19\ub124\uc694.</p><h2 data-notion-block-id=\\"150e548d-8a8e-80ee-9918-f2edf837d40c\\" id=\\"150e548d-8a8e-80ee-9918-f2edf837d40c\\">\ube4c\ub4dc \ub3c4\uad6c \uc5c6\uc774 \ub77c\uc774\ube0c\ub7ec\ub9ac \ubd88\ub7ec\uc624\uae30</h2><a href=\\"https://jvns.ca/blog/2024/11/18/how-to-import-a-javascript-library/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jvns.ca/blog/2024/11/18/how-to-import-a-javascript-library/</a><p data-notion-block-id=\\"150e548d-8a8e-80b5-b149-e467bba7b108\\">\ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uac00\uc838\uc624\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\uba74\uc11c \ubaa8\ub4c8\uc758 \uc885\ub958, importmaps, Node.js\uc5d0\uc11c\uc758 \ud30c\uc77c \uc720\ud615 \ud30c\uc545 \ubc29\ubc95\uc5d0 \ub300\ud55c \uac04\ub2e8\ud55c \ud6d1\uc5b4\ubcf4\uae30\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"150e548d-8a8e-80ef-8ced-e2c0797055f1\\" id=\\"150e548d-8a8e-80ef-8ced-e2c0797055f1\\">React 19\uc758 <code>&#x3C;Suspense></code> \ub3d9\uc791 \ubc29\uc2dd \ubcc0\uacbd</h2><a href=\\"https://github.com/facebook/react/issues/29898#issuecomment-2477449973\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/facebook/react/issues/29898#issuecomment-2477449973</a><p data-notion-block-id=\\"150e548d-8a8e-80ec-bc7d-d3950be0365c\\">React 19\ubc84\uc804 \uc774\uc804, React 19 RC0, React 19 RC1 \ubc84\uc804\uc758 fallback \ucee4\ubc0b \ubc29\uc2dd \ubcc0\uacbd\uc744 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"150e548d-8a8e-80bc-bce7-e2d7d072e4de\\" id=\\"150e548d-8a8e-80bc-bce7-e2d7d072e4de\\">\ub300\uccb4 \ud14d\uc2a4\ud2b8\ub294 \ub9cc\ub2a5\uc774 \uc544\ub2c8\ub2e4.</h2><a href=\\"https://www.nngroup.com/articles/alt-text-usability/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.nngroup.com/articles/alt-text-usability/</a><p data-notion-block-id=\\"150e548d-8a8e-80af-b41b-c38440b8e7ad\\">\uacbd\uc6b0\uc5d0 \ub530\ub77c\uc11c \uc2a4\ud06c\ub9b0 \ub9ac\ub354\ub97c \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ub300\uccb4 \ud14d\uc2a4\ud2b8\uac00 \ub3c4\uc6c0\uc774 \ub418\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\ub2e4\ub294 \uac83\uc744 \uc608\uc2dc\uc640 \ud568\uaed8 \uc548\ub0b4\ud574\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ub354 \uc790\uc138\ud55c \uc0ac\uc6a9 \ubc29\uc2dd\uc5d0 \ub300\ud55c \uae00\uc740 <a href=\\"https://ones-to-watch.ethansup.net/news/post/f1e3d4db-0127-4a32-865b-ffd34e238148#537af57e-1528-49ad-b4f0-d84ef1805d8a\\">BBC\uc758 Alt text \uac00\uc774\ub4dc\ub77c\uc778</a>\uae00\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"14ee548d-8a8e-80ac-ac2f-e75e1703ad33\\" id=\\"14ee548d-8a8e-80ac-ac2f-e75e1703ad33\\">\ub2e4\ub978 \ud568\uc218\uc5d0 setter\ub97c \uc804\ub2ec\ud558\uc9c0 \ub9c8\ub77c.</h2><a href=\\"https://matanbobi.dev/posts/stop-passing-setter-functions-to-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://matanbobi.dev/posts/stop-passing-setter-functions-to-components</a><p data-notion-block-id=\\"14ee548d-8a8e-8032-89f2-c2a247869ab2\\"><code>useState</code>\uc758 <code>setState</code>\ub97c \ub9e4\uac1c\ubcc0\uc218\ub85c \uc804\ub2ec\ud558\ub294 \ucf54\ub4dc\ub97c \uc9c0\uc801\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ucef4\ud3ec\ub10c\ud2b8\ub97c \ub9cc\ub4e4 \ub54c \ud754\ud788 \ud558\ub294 \ud589\ub3d9\uc774\uc9c0\ub9cc \ucef4\ud3ec\ub10c\ud2b8\uc758 \uc720\uc5f0\uc131\uc774 \ub5a8\uc5b4\uc9c0\uae30\uc5d0 \uc88b\uc9c0 \uc54a\uc740 \uad00\ud589 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"150e548d-8a8e-802b-ae2b-e8dcf4489a71\\" id=\\"150e548d-8a8e-802b-ae2b-e8dcf4489a71\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c \uad6c\ucd95 \uc2dc \uae30\uc874 \ub77c\uc774\ube0c\ub7ec\ub9ac \ud65c\uc6a9\ud558\uae30</h2><a href=\\"https://www.voorhoede.nl/en/blog/design-system-from-scratch-from-the-shelf/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.voorhoede.nl/en/blog/design-system-from-scratch-from-the-shelf/</a><p data-notion-block-id=\\"150e548d-8a8e-80e4-9923-d08645a0f3f5\\">\uae30\uc874 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud558\ub294 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc758 \uc7a5\ub2e8\uc810\uacfc \uc5b4\ub5bb\uac8c \uc120\ud0dd\ud558\ub294 \uac83\uc774 \uc88b\uc740\uc9c0, \uc2e4 \uc0ac\ub840\ub294 \uc5b4\ub5a0\ud55c\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"14ee548d-8a8e-80ce-af90-fa40c94a2c36\\" id=\\"14ee548d-8a8e-80ce-af90-fa40c94a2c36\\"><code>useSyncExternalStore</code>\uacfc \uc6d0\uc2dc \uac12</h2><a href=\\"https://www.nico.fyi/blog/be-careful-with-usesyncexternalstore\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.nico.fyi/blog/be-careful-with-usesyncexternalstore</a><p data-notion-block-id=\\"14ee548d-8a8e-8032-9aac-cb4c92d94536\\"><code>useSyncExternalStore</code>\ub97c \uc0ac\uc6a9\ud560 \uacbd\uc6b0 \uac12\uc774 \uc6d0\uc2dc \uac12\uc778\uc9c0 \ucc38\uc870 \uac12\uc778\uc9c0\ub97c \uc8fc\uc758\ud574\uc11c \uc0ac\uc6a9\ud574\uc57c \ud55c\ub2e4\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 <a href=\\"https://ones-to-watch.ethansup.net/news/post/ffe0e0a6-901b-4f3e-8b9a-0e48601ad787#aef423ee-c881-4803-a5c7-d940c6246140\\">\ub3d9\uc2dc\uc131 \ubaa8\ub4dc\uc758 \uc7a5\uc810\uc744 \uc804\ubd80 \uc0ac\uc6a9\ud558\uc9c0 \ubabb\ud55c\ub2e4\ub294 \uc810</a>\uc744 \uc778\uc9c0\ud558\uace0 \uc0ac\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"150e548d-8a8e-8017-b41d-f4b214cc257a\\" id=\\"150e548d-8a8e-8017-b41d-f4b214cc257a\\">Portal \uc18c\uac1c \uae00</h2><a href=\\"https://techhub.iodigital.com/articles/what-are-react-portals\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://techhub.iodigital.com/articles/what-are-react-portals</a><p data-notion-block-id=\\"150e548d-8a8e-80f3-bedc-d2626cd3f5ed\\"><code>React.createPortal</code>\uc774 \ubb34\uc5c7\uc774\uace0 \uc5b4\ub5a4 \uc7a5\uc810\uc774 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc774\uc9c0\ub9cc, \ubaa8\ub4e0 \ud504\ub808\uc784\uc6cc\ud06c\uc5d0 \ube44\uc2b7\ud55c \uae30\ub2a5\uc774 \uc788\uc73c\ub2c8 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \uc0ac\uc6a9\ud560 \ub54c \uc8fc\uc694\ud55c \uae30\ub2a5\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"150e548d-8a8e-80ae-9ce6-c254448df7a9\\" id=\\"150e548d-8a8e-80ae-9ce6-c254448df7a9\\">React Native \uae30\uc874 \uc571\uc5d0 \ud1b5\ud569\ud558\uae30</h2><a href=\\"https://www.callstack.com/blog/how-to-integrate-react-native-with-an-existing-app\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/how-to-integrate-react-native-with-an-existing-app</a><p data-notion-block-id=\\"150e548d-8a8e-80c7-b7db-ca802dc9f3b6\\">\uc2e4\uc81c \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0 \ud1b5\ud569\ud558\ub294 \uac83\uc740 \ub354 \uc5b4\ub835\uaca0\uc9c0\ub9cc, \uac04\ub2e8\ud558\uac8c \uae30\uc874 iOS/Android \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0 RN\uc744 \ud1b5\ud569\ud558\ub294 \uacfc\uc815\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);